<script setup>
import {Head,Link,router,useForm} from '@inertiajs/vue3';import {ref} from 'vue';import Errors from '../Components/Errors.vue';
const props=defineProps({questions:Object,counts:Object,filters:Object,subjects:Array});
const filters=ref({filter:props.filters.filter||'unreviewed',subject:props.filters.subject||'',search:props.filters.search||''});
const editing=ref(null),form=useForm({version_id:0,source_checked:false,answer_checked:false,decision:'correction',notes:''});
function open(q){editing.value=q.id;form.reset();form.version_id=q.version_id;form.clearErrors()}
function apply(){router.get('/admin/quality',filters.value,{preserveState:true})}
</script>
<template><Head title="Chef's quality queue"/><h1>Chef's Review</h1><p>Check references and answers, compare matching stems, and track corrections by question version.</p><div class="row"><Link href="/admin/reports">Learner reports</Link><Link href="/admin">Head Chef</Link></div>
<div class="panel"><div class="chips"><span>{{counts.total}} questions</span><span>{{counts.unreviewed}} awaiting review</span><span>{{counts.duplicates}} matching-stem groups</span><span>{{counts.missing_source}} missing references</span><span>{{counts.corrections}} need corrections</span></div><p class="muted">Matching stems are review flags. They remain available until Head Chef edits or retires an item. A recorded review applies only to the displayed version.</p>
<form class="form-grid" @submit.prevent="apply"><label>Queue<select v-model="filters.filter" @change="apply"><option value="unreviewed">Awaiting review</option><option value="duplicates">Matching stems</option><option value="missing_source">Missing reference</option><option value="corrections">Needs correction</option><option value="reviewed">Review completed</option><option value="all">All</option></select></label><label>Subject<select v-model="filters.subject" @change="apply"><option value="">All subjects</option><option v-for="s in subjects" :key="s">{{s}}</option></select></label><label>Question ID or text<input v-model="filters.search" maxlength="100"></label><button>Search</button></form></div>
<p v-if="!questions.data.length" class="notice">No questions match this queue.</p>
<article v-for="q in questions.data" :key="q.id" class="panel"><div class="row"><h2>{{q.id}} · v{{q.question.version}}</h2><span>{{q.subject}} · {{q.active?'Active':'Retired'}}</span></div><p v-if="q.duplicates.length" class="notice">Matching stems: {{q.duplicates.join(', ')}}</p><p class="pre">{{q.question.stem}}</p><details><summary>Answer, explanation, and reference</summary><p v-for="(o,i) in q.question.options" :key="i">{{String.fromCharCode(65+i)}}. {{o}}</p><p><strong>Answer {{q.question.key}}</strong> · {{q.question.rationale}}</p><p class="pre">{{q.question.source||'No reference supplied.'}}</p></details><div class="row spaced"><button @click="open(q)">Record review</button><Link :href="'/admin/questions?search='+encodeURIComponent(q.id)">Edit or retire question</Link></div>
<form v-if="editing===q.id" class="inset" @submit.prevent="form.post('/admin/quality/'+q.id,{preserveScroll:true,onSuccess:()=>editing=null})"><Errors :errors="form.errors"/><label class="check"><input type="checkbox" v-model="form.source_checked">I checked the cited reference</label><label class="check"><input type="checkbox" v-model="form.answer_checked">I checked the answer and explanation</label><label>Decision<select v-model="form.decision"><option value="correction">Needs correction</option><option value="checked">Review completed</option></select></label><label>Review notes<textarea v-model="form.notes" minlength="5" maxlength="3000" required rows="3"></textarea></label><button class="primary" :disabled="form.processing">Save version review</button></form>
<details v-if="q.history.length"><summary>Review history ({{q.history.length}})</summary><p v-for="h in q.history" :key="h.id">{{h.username}} · {{h.created_at}} · {{h.decision}}: {{h.notes}}</p></details></article>
<div class="row"><Link v-if="questions.prev_page_url" :href="questions.prev_page_url">Previous</Link><span>Page {{questions.current_page}} / {{questions.last_page}}</span><Link v-if="questions.next_page_url" :href="questions.next_page_url">Next</Link></div></template>
